insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_72_v1'
from (values
('127.484.d.1.A',3,'A technician answering a phone call from an anxious caregiver uses a calm tone, avoids slang, and shows courtesy. This is a respectful and professional:','["attitude", "inventory", "hairstyle", "salary"]'::jsonb,0,'Professional attitude shapes every communication.','original'),
('127.484.d.1.A',4,'Gossiping about a patient''s medicines in the break room breaks the professional standard of:','["speed", "confidentiality", "punctuality", "creativity"]'::jsonb,1,'Patient information must stay private.','original'),
('127.484.d.1.B',3,'For a patient who is blind, a technician should explain the label contents by:','["pointing at the label", "handing over a printout only", "reading the label aloud", "waving at the bottle"]'::jsonb,2,'Adapt the method to the patient''s need.','original'),
('127.484.d.1.B',4,'A child patient''s parent asks about a liquid medicine. The technician should speak to the parent as the:','["insurance agent", "delivery driver", "pharmacy owner", "caregiver who gives the doses"]'::jsonb,3,'Caregivers need clear instructions.','original'),
('127.484.d.1.C',3,'A technician who relays a doctor''s office question to the pharmacist is supporting communication between the pharmacy and the:','["prescriber''s office", "fire station", "bank", "parking lot"]'::jsonb,0,'Technicians bridge stakeholders.','original'),
('127.484.d.1.C',4,'When an insurance plan rejects a claim, the technician helps the pharmacist communicate with the plan, the patient, and the:','["landlord", "prescriber", "reporter", "neighbor"]'::jsonb,1,'Several stakeholders may need contact.','original'),
('127.484.d.2.A',3,'To interpret a medication order correctly, a technician reads the drug name, strength, route, and:','["color of ink", "pen brand", "frequency", "font size"]'::jsonb,2,'Orders list how often to give a drug.','original'),
('127.484.d.2.A',4,'A prescription reads ''amoxicillin 500 mg cap, 1 cap po tid.'' The abbreviation po means:','["under the tongue", "in the eye", "by injection", "by mouth"]'::jsonb,3,'po = per os, by mouth.','original'),
('127.484.d.2.B',3,'A pharmacy sends the doctor''s office a written request asking to change a drug because it is out of stock. This document is pharmacy:','["correspondence", "marketing", "payroll", "inventory count"]'::jsonb,0,'Correspondence is written communication.','original'),
('127.484.d.2.B',4,'A medication administration record in a hospital documents each dose given and the:','["patient''s hobby", "time it was given", "room color", "nurse''s phone model"]'::jsonb,1,'The MAR logs administration.','original'),
('127.484.d.2.C',3,'The medical term for a drug that eases pain is a(n):','["anticoagulant", "antacid", "analgesic", "antibiotic"]'::jsonb,2,'Analgesics relieve pain.','original'),
('127.484.d.2.C',4,'A pharmacy tech sees the term ''antihypertensive.'' This kind of medicine is used to treat:','["low blood sugar", "allergies", "infections", "high blood pressure"]'::jsonb,3,'Hypertension means high pressure.','original'),
('127.484.d.2.D',3,'A sig reads ''i gtt OU qid.'' The OU part means in:','["both eyes", "both ears", "the right ear", "the left eye"]'::jsonb,0,'OU = oculus uterque, both eyes.','original'),
('127.484.d.2.D',4,'On a sig, the code prn means to take the medicine:','["every morning", "only as needed", "before meals only", "at bedtime only"]'::jsonb,1,'prn = pro re nata, as needed.','original'),
('127.484.d.3.A',3,'Cytotoxic drugs, which can harm workers who touch them, are handled using gloves and disposed of in a container for:','["regular trash", "glass recycling", "hazardous drug waste", "paper recycling"]'::jsonb,2,'Hazardous drugs require special disposal.','original'),
('127.484.d.3.A',4,'A technician finds a spilled vial of a hazardous drug. The first action is to follow the pharmacy''s:','["sales plan", "parking rules", "lunch schedule", "spill procedure"]'::jsonb,3,'Spills follow written procedures.','original'),
('127.484.d.3.B',3,'A controlled-substance prescription must include the prescriber''s DEA number and the patient''s:','["address", "favorite drink", "shoe size", "hobbies"]'::jsonb,0,'Controlled prescriptions have extra required details.','original'),
('127.484.d.3.B',4,'A Schedule II prescription cannot be:','["signed", "refilled", "filled", "stored"]'::jsonb,1,'Schedule II drugs have no refills.','original'),
('127.484.d.3.C',3,'Controlled substances in the pharmacy are stored in a:','["customer waiting area", "open bin by the door", "locked, secure area", "front window display"]'::jsonb,2,'Security prevents theft and diversion.','original'),
('127.484.d.3.C',4,'When a shipment of controlled substances arrives, the receiving record must be checked and signed by a:','["customer", "visitor", "delivery driver only", "pharmacist"]'::jsonb,3,'Only authorized staff check CII receipts.','original'),
('127.484.d.3.D',3,'Heroin is classified as a Schedule I drug because it has a high potential for abuse and:','["no accepted medical use", "no side effects", "low risk", "many approved uses"]'::jsonb,0,'Schedule I has no accepted medical use.','original'),
('127.484.d.3.D',4,'Which schedule has the lowest abuse potential among the five?','["Schedule I", "Schedule V", "Schedule II", "Schedule III"]'::jsonb,1,'Schedule V is the lowest.','original'),
('127.484.d.3.E',3,'Medicines containing pseudoephedrine are kept behind the counter because they can be misused to make illegal:','["antibiotics", "insulin", "methamphetamine", "vitamins"]'::jsonb,2,'The Combat Meth Epidemic Act limits sales.','original'),
('127.484.d.3.E',4,'Federal law requires a store to record each pseudoephedrine buyer''s name, ID, and the:','["favorite brand of soap", "buyer''s weight", "car color", "amount purchased"]'::jsonb,3,'Sales are logged and limited.','original'),
('127.484.d.3.F',3,'When a manufacturer pulls an unsafe batch of tablets from the market, the pharmacy must remove the product listed in the:','["recall notice", "menu", "coupon", "sales flyer"]'::jsonb,0,'Recalls identify affected lots.','original'),
('127.484.d.3.F',4,'After removing recalled stock, the pharmacy records how many units were found and:','["the day''s weather", "how they were returned or destroyed", "the shelf color", "the clerk''s age"]'::jsonb,1,'Recalls require documentation.','original'),
('127.484.d.3.G',3,'Tasks a technician may legally perform are limited by the state''s:','["parking policy", "sales target", "scope of practice", "uniform code only"]'::jsonb,2,'Scope of practice defines allowed duties.','original'),
('127.484.d.3.G',4,'A technician is asked to counsel a patient on side effects. Because counseling is a pharmacist duty, the technician should:','["skip the question", "guess the answer", "answer anyway", "refer the patient to the pharmacist"]'::jsonb,3,'Stay within scope.','original'),
('127.484.d.4.A',3,'Lipitor is a brand-name drug that lowers cholesterol. Its drug class is the:','["statin", "diuretic", "antihistamine", "antibiotic"]'::jsonb,0,'Atorvastatin lowers cholesterol.','original'),
('127.484.d.4.A',4,'Metformin is used for the indication of:','["high blood pressure", "type 2 diabetes", "asthma", "epilepsy"]'::jsonb,1,'Metformin lowers blood glucose.','original'),
('127.484.d.4.B',3,'Taking warfarin with some other drugs can raise the risk of:','["sleepiness only", "sneezing", "bleeding", "hair loss only"]'::jsonb,2,'Warfarin interactions affect clotting.','original'),
('127.484.d.4.B',4,'A drug that should not be used with another because the combination is dangerous has a(n):','["expiration", "brand name", "trivial flavor", "major interaction"]'::jsonb,3,'Major interactions are flagged for the pharmacist.','original'),
('127.484.d.4.C',3,'A drug with a narrow therapeutic index requires blood levels to be checked because a small change in dose can cause:','["toxicity or treatment failure", "a new flavor", "faster shipping", "a change in tablet color only"]'::jsonb,0,'NTI drugs have small safety margins.','original'),
('127.484.d.4.C',4,'Which of these is commonly considered an NTI drug?','["loratadine", "phenytoin", "acetaminophen", "vitamin C"]'::jsonb,1,'Phenytoin has a narrow range.','original'),
('127.484.d.4.D',3,'A technician looking for the legal standards for compounding would use the United States:','["Atlas", "Census", "Pharmacopeia", "Encyclopedia"]'::jsonb,2,'USP lists compounding standards.','original'),
('127.484.d.4.D',4,'A quick online drug reference is helpful, but the technician must make sure the source is current and:','["colorful", "free of numbers", "loud", "reliable"]'::jsonb,3,'Check reliability.','original'),
('127.484.d.5.A',3,'A prescription is missing the patient''s date of birth. The technician should note the item as:','["incomplete", "free", "finished", "refillable"]'::jsonb,0,'Required items must be present.','original'),
('127.484.d.5.A',4,'Besides the drug name and strength, a medication order for a hospital patient must show the route and the:','["tech''s initials only", "prescriber''s signature or authentication", "patient''s hairstyle", "pharmacy''s slogan"]'::jsonb,1,'Orders must be authenticated.','original'),
('127.484.d.5.B',3,'For a patient who prefers written information, a technician can provide a printed sheet in a language the patient:','["mispronounces", "dislikes", "understands", "never uses"]'::jsonb,2,'Choose an appropriate modality.','original'),
('127.484.d.5.B',4,'Using a video relay interpreter for a deaf patient is an example of choosing the right communication:','["coupon", "password", "receipt", "modality"]'::jsonb,3,'The method must fit the patient.','original'),
('127.484.d.5.C',3,'Gathering a patient''s address, phone number, and insurance information is collecting:','["demographic information", "clinical results", "chemical formulas", "lab values"]'::jsonb,0,'Demographics identify the patient.','original'),
('127.484.d.5.C',4,'Recording a patient''s height, weight, and allergies is entering:','["stock numbers", "clinical information", "advertising", "billing codes"]'::jsonb,1,'Clinical data support dosing and safety.','original'),
('127.484.d.5.D',3,'Before preparing an intravenous admixture in a hood, a technician must first perform:','["a sales call", "a coffee break", "hand hygiene and garbing", "an inventory count"]'::jsonb,2,'Aseptic technique begins with hand hygiene.','original'),
('127.484.d.5.D',4,'The air in an IV compounding hood moves in a direction that carries particles away from the product. This is called:','["turbulent airflow", "still air", "random wind", "laminar airflow"]'::jsonb,3,'Laminar flow keeps product clean.','original'),
('127.484.d.5.E',3,'A patient with diabetes needs supplies to check blood glucose, which includes a meter and:','["test strips", "bandage tape only", "rubber bands", "thermometers only"]'::jsonb,0,'Strips test the sample.','original'),
('127.484.d.5.E',4,'A nebulizer is used to turn liquid medicine into a mist that the patient breathes through a:','["straw", "mask or mouthpiece", "syringe", "bandage"]'::jsonb,1,'Nebulizers deliver inhaled drugs.','original'),
('127.484.d.5.F',3,'Each medicine product has a unique 10- or 11-digit number that identifies the manufacturer and product, called the:','["phone code", "social number", "National Drug Code", "zip code"]'::jsonb,2,'NDC identifies the product.','original'),
('127.484.d.5.F',4,'If a bottle has a beyond-use date shorter than the manufacturer''s expiration date, the pharmacy must follow the:','["price tag", "later date", "color of the label", "earlier date"]'::jsonb,3,'Use the shorter date.','original'),
('127.484.d.5.G',3,'Using a fresh pair of gloves for each task prevents:','["cross-contamination", "bottles from cracking", "gloves from selling", "labels from fading"]'::jsonb,0,'Changing gloves limits germs.','original'),
('127.484.d.5.G',4,'Washing hands with soap and water is preferred over sanitizer when hands are visibly:','["dry", "soiled", "cool", "clean"]'::jsonb,1,'Soap removes visible soil.','original'),
('127.484.d.6.A',3,'Insulin, heparin, and opioids are often called high-alert medications because mistakes with them can cause:','["bad tastes", "color changes", "serious harm", "small delays"]'::jsonb,2,'High-alert drugs are riskier.','original'),
('127.484.d.6.A',4,'The drug names Celebrex and Cerebyx are an example of a look-alike/sound-alike pair, so the pharmacy may store them in:','["the front window", "the same bin", "a personal drawer", "separate places"]'::jsonb,3,'Separation prevents mix-ups.','original'),
('127.484.d.6.B',3,'A label written as hydrOXYzine and hydrALAZINE uses capital letters to highlight differences. This strategy is:','["Tall Man lettering", "Block printing", "Bold naming", "Title casing"]'::jsonb,0,'Tall Man lettering helps.','original'),
('127.484.d.6.B',4,'Asking the patient to state their full name and birth date before handing over a bag is using two:','["coupons", "patient identifiers", "receipts", "pens"]'::jsonb,1,'Two identifiers confirm the right patient.','original'),
('127.484.d.6.C',3,'An order for 500 mg of a drug that is normally given in 5 mg doses is an example of a(n):','["brand switch", "early refill", "abnormal dose", "generic substitution"]'::jsonb,2,'A hundredfold dose is a red flag.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_72_v1'
from (values
('127.484.d.6.C',4,'A prescription with an illegible handwritten dose should be:','["guessed", "filled quickly", "thrown away", "clarified with the prescriber"]'::jsonb,3,'Never guess.','original'),
('127.484.d.6.D',3,'A technician who notices a patient allergic to penicillin has a new penicillin prescription should immediately alert the:','["pharmacist", "cashier", "driver", "customer behind them"]'::jsonb,0,'Safety issues go to the pharmacist.','original'),
('127.484.d.6.D',4,'A technician sees that the dose on a pediatric prescription is far higher than the weight-based dose. The technician should:','["call the insurance company", "stop and tell the pharmacist", "fill it and hope", "relabel it"]'::jsonb,1,'Flag unusual doses.','original'),
('127.484.d.6.E',3,'An error that is caught before it reaches the patient is a:','["harm event", "recall", "near miss", "refill"]'::jsonb,2,'Near misses are caught early.','original'),
('127.484.d.6.E',4,'An unexpected harmful result from a medication given correctly is an adverse:','["price change", "stock level", "delivery", "drug reaction"]'::jsonb,3,'ADRs happen even without errors.','original'),
('127.484.d.7.A',3,'In a community pharmacy, a prescription starts with the prescriber''s order, which may be handwritten, phoned in, faxed, or:','["electronically prescribed", "painted", "mailed in a bottle", "tweeted"]'::jsonb,0,'E-prescribing is common.','original'),
('127.484.d.7.A',4,'A prescription received by phone must be reduced to writing or electronic form by the:','["customer", "pharmacist", "delivery driver", "insurance clerk"]'::jsonb,1,'Only pharmacists take new oral orders.','original'),
('127.484.d.7.B',3,'Verifying a prescription includes checking the patient''s name, the drug, and the:','["tech''s lunch", "bottle''s color", "prescriber''s authority", "pharmacy''s carpet"]'::jsonb,2,'Prescribers must be authorized.','original'),
('127.484.d.7.B',4,'A pharmacist can confirm an unfamiliar prescriber is legitimate by checking the prescriber''s:','["clinic''s slogan", "car", "taste in music", "license and DEA registration"]'::jsonb,3,'Verification prevents fraud.','original'),
('127.484.d.7.C',3,'After entering a prescription into the computer, the technician compares the entered sig with the:','["original prescription", "weather report", "receipt tape", "calendar"]'::jsonb,0,'Check entry against the source.','original'),
('127.484.d.7.C',4,'Selecting the wrong patient profile during data entry could lead to a dispensing:','["parade", "error", "discount", "holiday"]'::jsonb,1,'Profile errors are dangerous.','original'),
('127.484.d.7.D',3,'When counting tablets from a stock bottle, the technician should confirm the NDC matches the one on the:','["uniform", "paycheck", "label and the drug being dispensed", "door"]'::jsonb,2,'Match NDCs.','original'),
('127.484.d.7.D',4,'Filling a prescription for a liquid antibiotic powder requires adding the correct amount of:','["sugar", "oil", "salt", "water"]'::jsonb,3,'Reconstitution uses water.','original'),
('127.484.d.7.E',3,'Before a nurse gives an injection, the order is checked against the five rights: right patient, right drug, right dose, right route, and right:','["time", "coupon", "brand", "color"]'::jsonb,0,'The five rights prevent errors.','original'),
('127.484.d.7.E',4,'A medicine ordered ''IV'' is administered:','["on the skin", "into a vein", "under the tongue", "by mouth"]'::jsonb,1,'IV = intravenous.','original'),
('127.484.d.7.F',3,'In a busy pharmacy, a prescription moves from intake to data entry, then to filling, then to pharmacist verification, and finally to:','["the shredder", "the supplier", "pickup or delivery", "the lobby"]'::jsonb,2,'Workflow ends with dispensing.','original'),
('127.484.d.7.F',4,'A prescription waiting for an insurance approval is placed in a queue called:','["finished", "expired", "recalled", "on hold"]'::jsonb,3,'Workflow queues track status.','original'),
('127.484.d.7.G',3,'A fixed amount that a patient pays at pickup for each prescription is the:','["copay", "tax", "premium", "deductible"]'::jsonb,0,'Copay is a set fee.','original'),
('127.484.d.7.G',4,'When a claim is sent to the insurer electronically and returns a response in seconds, the process is called:','["paper filing", "online adjudication", "manual counting", "refilling"]'::jsonb,1,'Adjudication decides payment.','original'),
('127.484.d.8.A',3,'A child weighs 20 kg and the order is 10 mg per kg once. The dose is:','["2 mg", "30 mg", "200 mg", "100 mg"]'::jsonb,2,'20 x 10 = 200.','original'),
('127.484.d.8.A',4,'An adult order is 15 mg per kg per day divided into 3 doses. For a 60 kg adult each dose is:','["100 mg", "45 mg", "900 mg", "300 mg"]'::jsonb,3,'15 x 60 = 900 mg/day; 900 / 3 = 300 mg.','original'),
('127.484.d.8.B',3,'One teaspoon equals about:','["5 mL", "50 mL", "30 mL", "15 mL"]'::jsonb,0,'1 tsp = 5 mL.','original'),
('127.484.d.8.B',4,'A dose of 0.25 g expressed in milligrams is:','["2500 mg", "250 mg", "2.5 mg", "25 mg"]'::jsonb,1,'1 g = 1000 mg.','original'),
('127.484.d.8.C',3,'An IV runs at 1000 mL over 8 hours. The rate is:','["250 mL/hr", "8 mL/hr", "125 mL/hr", "80 mL/hr"]'::jsonb,2,'1000 / 8 = 125.','original'),
('127.484.d.8.C',4,'A 500 mL bag must infuse over 4 hours with a 15 gtt/mL set. The drops per minute are about:','["15", "60", "125", "31"]'::jsonb,3,'500 x 15 = 7500; / 240 min = 31.','original'),
('127.484.d.8.D',3,'A prescription is for 2 tablets daily with a quantity of 60. The days supply is:','["30", "15", "120", "60"]'::jsonb,0,'60 / 2 = 30.','original'),
('127.484.d.8.D',4,'An inhaler has 200 puffs and the patient uses 2 puffs twice daily. The days supply is:','["100", "50", "25", "200"]'::jsonb,1,'4 puffs/day; 200 / 4 = 50.','original'),
('127.484.d.8.E',3,'A TPN bag needs 2 g of amino acids per kg for a 50 kg patient. The total amino acids needed is:','["200 g", "52 g", "100 g", "25 g"]'::jsonb,2,'2 x 50 = 100.','original'),
('127.484.d.8.E',4,'If amino acid solution is 10 percent, then 100 g of amino acid requires a volume of:','["100 mL", "10 mL", "10000 mL", "1000 mL"]'::jsonb,3,'10 g per 100 mL, so 100 g = 1000 mL.','original'),
('127.484.d.8.F',3,'To compound 200 g of an ointment containing 5 percent drug by weight, you need how much drug?','["10 g", "5 g", "1 g", "20 g"]'::jsonb,0,'0.05 x 200 = 10.','original'),
('127.484.d.8.F',4,'If 60 g of a cream needs 2 percent of an active ingredient, the weight of that ingredient is:','["0.12 g", "1.2 g", "2 g", "12 g"]'::jsonb,1,'0.02 x 60 = 1.2.','original'),
('127.484.d.8.G',3,'A 10 percent weight/volume solution contains how many grams in 100 mL?','["100 g", "0.1 g", "10 g", "1 g"]'::jsonb,2,'w/v percent is g per 100 mL.','original'),
('127.484.d.8.G',4,'How many grams of dextrose are needed for 500 mL of a 5 percent w/v solution?','["2.5 g", "50 g", "5 g", "25 g"]'::jsonb,3,'5 g per 100 mL x 5 = 25.','original'),
('127.484.d.8.H',3,'A drug costs the pharmacy 8 dollars and sells for 12 dollars. The markup in dollars is:','["4", "8", "12", "20"]'::jsonb,0,'12 - 8 = 4.','original'),
('127.484.d.8.H',4,'A medication costs 40 dollars and the pharmacy adds a 25 percent markup. The selling price is:','["65 dollars", "50 dollars", "45 dollars", "60 dollars"]'::jsonb,1,'40 x 1.25 = 50.','original'),
('127.484.d.9.A',3,'A machine that stores and counts pills and delivers them to the pharmacist is an automated:','["cash register", "phone", "dispensing cabinet", "printer"]'::jsonb,2,'Automated cabinets store drugs.','original'),
('127.484.d.9.A',4,'Hospital nursing units use automated dispensing cabinets that log which nurse took which drug and:','["what they ate", "the nurse''s age", "who parked", "when it was removed"]'::jsonb,3,'Cabinets track access.','original'),
('127.484.d.9.B',3,'Pharmacy dispensing software keeps each patient''s information in a profile that includes allergies and:','["medication history", "pet''s name", "car model", "favorite song"]'::jsonb,0,'Profiles aid safety.','original'),
('127.484.d.9.B',4,'If the software warns of a possible drug interaction, the technician should alert the:','["manager", "pharmacist", "courier", "salesperson"]'::jsonb,1,'Pharmacists review alerts.','original'),
('127.484.d.9.C',3,'Sending patient information by regular unsecured text message could violate:','["holiday rules", "building codes", "privacy rules", "traffic laws"]'::jsonb,2,'Texts must protect PHI.','original'),
('127.484.d.9.C',4,'When faxing a prescription transfer, the technician should use a cover sheet that includes a statement about:','["sports", "advertising", "weather", "confidentiality"]'::jsonb,3,'Cover sheets protect privacy.','original'),
('127.484.d.9.D',3,'A barcode scanner used when filling prescriptions is an example of an input:','["device", "law", "recipe", "drug"]'::jsonb,0,'Scanners input data.','original'),
('127.484.d.9.D',4,'A label printer that prints the prescription label is an example of a(n):','["power supply", "output device", "input device only", "storage shelf"]'::jsonb,1,'Printers output data.','original'),
('127.484.d.9.E',3,'A technician can look up a tablet''s imprint, shape, and color using a(n):','["road map", "calendar", "pill identifier tool", "calculator only"]'::jsonb,2,'Imprint search identifies tablets.','original'),
('127.484.d.9.E',4,'When searching for drug information online, the best sources include government sites and:','["social media posts", "gossip pages", "advertisements", "professional pharmacy references"]'::jsonb,3,'Choose reliable references.','original'),
('127.484.d.10.A',3,'A pharmacy study of a new drug based on only a few patients with no comparison group has weak:','["validity", "packaging", "marketing", "pricing"]'::jsonb,0,'Small, uncontrolled studies are weak.','original'),
('127.484.d.10.A',4,'Repeating a study and getting the same results shows the study is:','["unfair", "reliable", "expensive", "secret"]'::jsonb,1,'Reliability is consistency.','original'),
('127.484.d.10.B',3,'A good place to find valid drug information is a peer-reviewed:','["coupon book", "billboard", "journal", "flyer"]'::jsonb,2,'Peer review adds quality control.','original'),
('127.484.d.10.B',4,'Before relying on an article, a technician checks the author''s credentials and the publication:','["logo", "length", "font", "date"]'::jsonb,3,'Information may be outdated.','original'),
('127.484.d.10.C',3,'When using online resources in a pharmacy, a technician should never post a patient''s:','["personal information", "school mascot", "favorite books", "opinions on weather"]'::jsonb,0,'Patient data must stay private.','original'),
('127.484.d.10.C',4,'A pharmacy website that asks patients to log in should use a secure connection that begins with:','["maybe", "https", "ftp", "gossip"]'::jsonb,1,'HTTPS encrypts data.','original'),
('127.484.d.10.D',3,'A website run by a drug company about its own drug may be biased because the company wants to:','["hide the label", "lose money", "sell the drug", "close the store"]'::jsonb,2,'Check for conflicts of interest.','original'),
('127.484.d.10.D',4,'To analyze whether an online article is trustworthy, a technician compares it with other:','["advertisements", "coupons", "jokes", "independent sources"]'::jsonb,3,'Cross-checking improves reliability.','original'),
('127.484.d.10.E',3,'A recent pharmacy innovation in which a robot prepares IV medications is called IV:','["compounding robotics", "gardening", "paper filing", "phone tag"]'::jsonb,0,'Robots reduce errors in compounding.','original'),
('127.484.d.10.E',4,'Technology that lets patients refill prescriptions with a smartphone app is an example of an advance in pharmacy:','["taxation", "convenience", "demolition", "farming"]'::jsonb,1,'Apps improve access.','original')
